@@ -72,16 +72,68 @@ describe('installConsole', () => {
     expect(events[1]?.data['message']).toBe('debug line');
   });

+  it('captures a failed console.assert as CONSOLE_ERROR, as DevTools shows it', () => {
+    const { emit, events } = collect();
+    teardown = installConsole(emit);
+
+    console.assert(false, 'invariant broke', 7);
+    console.assert(undefined);
+
+    // Node's own console.assert delegates to console.warn (a browser's does not), so look only at
+    // the error channel this change adds.
+    const errors = events.filter((e) => EventType.CONSOLE_ERROR === e.type);
+    expect(errors).toHaveLength(2);
+    expect(errors[0]?.data['message']).toBe('Assertion failed: invariant broke 7');
+    expect(errors[1]?.data['message']).toBe('Assertion failed');
+  });
+
+  it('emits nothing for a console.assert that passes', () => {
+    const { emit, events } = collect();
+    teardown = installConsole(emit);
+
+    console.assert(true, 'fine');
+
+    expect(events).toHaveLength(0);
+  });
+
+  it('still installs, and tears down cleanly, on a console shim without assert', () => {
+    const descriptor = Object.getOwnPropertyDescriptor(console, 'assert');
+    const beforeLog = console.log;
+    Reflect.deleteProperty(console, 'assert');
+    try {
+      const { emit, events } = collect();
+      let t: Teardown | undefined;
+      expect(() => {
+        t = installConsole(emit);
+      }).not.toThrow();
+      console.error('still captured');
+      expect(events.some((e) => EventType.CONSOLE_ERROR === e.type)).toBe(true);
+      window.dispatchEvent(
+        new ErrorEvent('error', { message: 'boom', error: new Error('boom'), bubbles: false }),
+      );
+      expect(events.filter((e) => e.type === EventType.ERROR_UNCAUGHT)).toHaveLength(1);
+      t?.();
+      expect(console.log).toBe(beforeLog);
+      expect(Object.getOwnPropertyDescriptor(console, 'assert')).toBeUndefined();
+    } finally {
+      if (descriptor) {
+        Object.defineProperty(console, 'assert', descriptor);
+      }
+    }
+  });
+
   it('restores the original console methods (identity) on teardown', () => {
     const beforeLog = console.log;
     const beforeWarn = console.warn;
     const beforeError = console.error;
+    const beforeAssert = console.assert;
     const t = installConsole(collect().emit);
     expect(console.error).not.toBe(beforeError);
     t();
     expect(console.log).toBe(beforeLog);
     expect(console.warn).toBe(beforeWarn);
     expect(console.error).toBe(beforeError);
+    expect(console.assert).toBe(beforeAssert);
   });
 });

